import type { ComponentProps, CSSProperties, ElementType, ReactNode } from 'react'
import { cn } from 'cn'
import type { AccentColor } from '@/lib/theme/theme'
type TypographyProps = {as?:ElementType;size?:1|2|3|4|5|6|7|8|9;color?:AccentColor;highContrast?:boolean;weight?:'light'|'regular'|'medium'|'bold';children?:ReactNode;className?:string;href?:string;target?:string;rel?:string;style?:CSSProperties}
function Text({as:Tag='span',size=3,color,highContrast,weight,className,style,...props}:TypographyProps& Omit<ComponentProps<'span'>,'color'>) {
 return <Tag {...props} data-color={color} data-high-contrast={highContrast||undefined} data-weight={weight} className={cn('ds-typography',className)} style={{'--type-size':`var(--font-size-${size})`,'--type-line':`var(--line-height-${size})`,'--type-spacing':`var(--letter-spacing-${size})`,...style}}/>
}
function Link({underline='auto',...props}:TypographyProps & Omit<ComponentProps<'a'>,'color'> & {underline?:'auto'|'always'|'none'}) {return <Text as="a" {...props} data-underline={underline} className={cn('ds-link-typography',props.className)}/>}
function Heading({size=6,...props}:TypographyProps) {return <Text as="h2" size={size} {...props} className={cn('ds-heading',props.className)} style={{...props.style,'--type-line':`var(--heading-line-height-${size})`} as CSSProperties}/> }
